// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Enzimler, metabolizma, fotosentez ve solunum (zor).
const ozBiology7Zor = <(String, String, List<String>, String)>[
  ('NADP⁺ ile NAD⁺ arasındaki yapısal fark nedir?', 'NADP⁺ riboz şekerlerinden birine bağlı fazladan bir fosfat taşır.', ['NADP⁺\'da adenin yerine guanin bulunur.', 'NADP⁺\'da nikotinamit halkası bulunmaz.', 'NADP⁺ iki ayrı nükleotitten değil, üç nükleotitten oluşur.'], 'NADP⁺, NAD⁺\'nın adenine bağlı ribozun 2\' karbonuna ek bir fosfat grubu takılmış hâlidir.'),
  ('Elektronların indirgenme potansiyeli düşük olan bir taşıyıcıdan yüksek olana geçmesi sırasında ne olur?', 'Serbest enerji açığa çıkar.', ['Ortamdan enerji soğurulur.', 'Elektronlar ATP\'ye dönüşür.', 'Taşıyıcılar kalıcı olarak bozulur.'], 'Elektronlar indirgenme potansiyeli daha pozitif olan alıcıya kendiliğinden akar ve bu akış serbest enerji verir; ETS bu ilkeye dayanır.'),
  ('ATP hidrolizinde açığa çıkan enerjinin yüksek olmasının yapısal nedenlerinden biri hangisidir?', 'Art arda bağlı negatif yüklü fosfat gruplarının birbirini itmesi', ['Adeninin halkasının kolayca kırılması', 'Riboz şekerinin glikoza dönüşmesi', 'Fosfat gruplarının pozitif yüklü olması'], 'Üç fosfat grubundaki negatif yükler birbirini iter; uç fosfat koptuğunda bu gerilim azalır ve ürünler daha kararlı hâle gelir.'),
  ('Bir enzim çözeltisi diyaliz torbasına konup saf suda bekletildiğinde enzimin etkinliğini yitirdiği, dışarıdaki suyun geri eklenmesiyle etkinliğin geri döndüğü görülüyor. Bu sonuç hangisini gösterir?', 'Enzimin zardan geçebilen küçük bir kofaktöre ihtiyacı vardır.', ['Enzim protein değil, bir RNA molekülüdür.', 'Enzimin aktif bölgesi suyla kalıcı olarak bozulmuştur.', 'Enzim diyalizle iki ayrı alt birime ayrılıp yok olmuştur.'], 'Diyalizde büyük protein torbada kalır, küçük kofaktörler dışarı geçer; dış sıvı geri verilince kofaktör geri döner ve etkinlik yeniden kazanılır.'),
  ('Bir enzim genindeki mutasyonla aktif bölgeden uzak bir amino asit değişiyor ve enzim etkinliğini yitiriyor. Bunun en olası açıklaması nedir?', 'Değişiklik proteinin katlanmasını bozup aktif bölgenin biçimini değiştirmiştir.', ['Aktif bölgeden uzak amino asitler substratla doğrudan tepkimeye girer.', 'Mutasyon enzimin substratını başka bir molekülle değiştirmiştir.', 'Enzimler yalnız uzak bölgelerinden substrat bağlar.'], 'Uzak bir değişiklik katlanmayı bozarsa aktif bölgenin geometrisi de bozulur ve katalitik etkinlik kaybolabilir.'),
  ('Karboksilaz enzimlerinin CO₂ bağlamasına yardım eden ve çiğ yumurta akındaki avidin proteini tarafından bağlanabilen vitamin hangisidir?', 'Biyotin', ['Folik asit', 'Kobalamin', 'Retinol'], 'Biyotin, pirüvat karboksilaz gibi karboksilazların koenzimidir; avidin biyotini sıkıca bağlayarak emilimini engeller.'),
  ('Su ya da yükseltgenme kullanmadan bağ koparan veya çift bağa grup ekleyen enzimler (örneğin aldolaz) hangi sınıftadır?', 'Liyazlar', ['Ligazlar', 'Hidrolazlar', 'Transferazlar'], 'EC 4 liyazlar hidroliz ya da yükseltgenme olmadan bağ kırar; aldolaz fruktoz-1,6-bisfosfatı iki üç karbonluya ayırır.'),
  ('Michaelis-Menten kinetiğine uyan bir enzimde hızın Vmax\'ın %90\'ına ulaşması için substrat derişimi Km\'nin kaç katı olmalıdır?', '9 katı', ['2 katı', '90 katı', '3 katı'], '0,9 = [S]/(Km+[S]) ⇒ [S] = 9·Km. Doygunluğa yaklaşmak için derişimi çok artırmak gerekir.'),
  ('Michaelis-Menten kinetiğine uyan bir enzimde substrat derişimi Km değerinin üç katı olduğunda tepkime hızı en yüksek hızın yüzde kaçıdır?', '75', ['33', '50', '90'], 'v/Vmax = [S]/(Km+[S]) = 3Km/(Km+3Km) = 3/4, yani %75.'),
  ('Bir enzimin \'dönüşüm sayısı\' (kcat) neyi ifade eder?', 'Doymuş bir enzim molekülünün birim zamanda ürüne çevirdiği substrat sayısını', ['Enzimin ömrü boyunca kaç kez sentezlendiğini', 'Bir substratın kaç farklı enzimce tanındığını', 'Enzimin aktif bölgesindeki amino asit sayısını'], 'kcat = Vmax/[toplam enzim]; bir enzim molekülünün saniyede katalizlediği en fazla tepkime sayısıdır.'),
  ('Lineweaver-Burk grafiğinde 1/v ile 1/[S] arasındaki doğrunun dikey ekseni kestiği nokta neye eşittir?', '1/Vmax', ['1/Km', '−1/Km', 'Km/Vmax'], 'Çift ters çizimde dikey eksen kesişimi 1/Vmax, yatay eksen kesişimi −1/Km, eğim ise Km/Vmax\'tır.'),
  ('Lineweaver-Burk çiziminde doğrunun yatay ekseni −0,5 mM⁻¹ noktasında kestiği bir enzimin Km değeri kaçtır?', '2 mM', ['0,5 mM', '−2 mM', '5 mM'], 'Yatay eksen kesişimi −1/Km\'dir: −1/Km = −0,5 ⇒ Km = 2 mM.'),
  ('Yarışmasız (non-kompetitif) bir inhibitör enzimin aktif bölgesinden başka bir yere bağlanır. Bu inhibitör Km ve Vmax\'ı nasıl etkiler?', 'Vmax azalır, Km değişmez.', ['Km artar, Vmax değişmez.', 'İkisi de artar.', 'Km azalır, Vmax değişmez.'], 'Klasik yarışmasız inhibisyonda inhibitör substrat bağlanmasını değiştirmez ama enzim-substrat kompleksinin ürün vermesini engeller; etkin enzim miktarı azalmış gibi olur.'),
  ('Bir enzim deneyinde inhibitör eklenince Lineweaver-Burk doğrularının dikey eksende aynı noktada kesiştiği, ancak eğimin arttığı görülüyor. İnhibisyon türü hangisidir?', 'Yarışmalı inhibisyon', ['Yarışmasız inhibisyon', 'Substrat fazlası inhibisyonu', 'Allosterik etkinleştirme'], 'Dikey kesişimin (1/Vmax) aynı kalması Vmax\'ın değişmediğini gösterir; bu yarışmalı inhibisyonun özelliğidir.'),
  ('Kanser tedavisinde kullanılan metotreksat, folik asit metabolizmasındaki dihidrofolat redüktaz enzimini substrata benzeyerek engeller. Bu ilacın etki biçimi hangisidir?', 'Yarışmalı inhibisyon', ['Geri besleme etkinleştirmesi', 'Substrat düzeyinde fosforilasyon', 'Kofaktör sağlama'], 'Metotreksat dihidrofolatın yapısal benzeridir ve aktif bölgeye çok sıkı bağlanarak yarışmalı inhibitör gibi davranır; hızlı bölünen hücreler nükleotit sentezleyemez.'),
  ('Sülfonamit grubu antibiyotikler bakterilerin folik asit sentezinde kullandığı PABA\'ya (para-aminobenzoik asit) benzer. İnsanlara görece zararsız olmalarının nedeni nedir?', 'İnsanlar folik asidi sentezlemez, besinlerle hazır alır.', ['İnsan hücrelerinde PABA çok daha büyük bir moleküldür.', 'İnsanlarda folik asidin hiçbir görevi yoktur.', 'Sülfonamitler yalnız bakteri zarından geçebilir.'], 'Sülfonamitler PABA ile yarışarak bakteride folat sentezini engeller; insanda bu yol olmadığı için hedef enzim bulunmaz.'),
  ('Bir inhibitörün enzime geri dönüşümlü mü yoksa geri dönüşümsüz mü bağlandığını anlamak için en uygun deney hangisidir?', 'Enzim-inhibitör karışımını diyalizle süzüp etkinliğin geri gelip gelmediğine bakmak', ['Ortamın sıcaklığını 0 °C\'ye düşürmek', 'Enzim miktarını yarıya indirip hızı ölçmek', 'Ortama ikinci bir substrat eklemek'], 'Diyaliz serbest inhibitörü uzaklaştırır; geri dönüşümlü bağlanan inhibitör ayrılır ve etkinlik geri gelir, kovalent bağlanan ise ayrılmaz.'),
  ('Aspirinin ağrı ve ateşi azaltma etkisi, siklooksijenaz (COX) enziminin aktif bölgesindeki bir serin amino asidine asetil grubu bağlamasına dayanır. Bu inhibisyon türü hangisidir?', 'Kovalent bağla gerçekleşen geri dönüşümsüz inhibisyon', ['Substrat fazlalığıyla aşılabilen yarışmalı inhibisyon', 'Ürün birikmesiyle gelişen geri besleme inhibisyonu', 'Kofaktör eksikliğine bağlı geçici inhibisyon'], 'Aspirin COX\'u asetilleyerek kalıcı biçimde etkisizleştirir; etki ancak yeni enzim sentezlenince ortadan kalkar.'),
  ('Aspartat transkarbamoilaz, pirimidin sentez yolunun ilk enzimidir ve yolun son ürünlerinden CTP ile baskılanır, ATP ile uyarılır. ATP ile uyarılmasının hücre açısından anlamı nedir?', 'Pürin bol olduğunda pirimidin üretimini artırarak iki nükleotit türünü dengelemek', ['ATP\'yi doğrudan CTP\'ye dönüştürmek', 'Hücrenin enerjisini düşürmek için ATP\'yi tüketmek', 'Pürin sentezini tamamen durdurmak'], 'ATP bir pürin nükleotitidir; bolken pirimidin sentezini hızlandırması, DNA ve RNA için gerekli pürin ve pirimidinlerin dengeli üretilmesini sağlar.'),
  ('Dallanmış bir metabolik yolda iki son ürünün her biri, ortak basamağın enziminin yalnızca bir kısmını baskılıyor. Bu düzenlemenin yararı nedir?', 'Bir ürün bol diye diğer ürünün üretiminin de tamamen durmasını önlemek', ['Ortak enzimin hiçbir koşulda yavaşlamamasını sağlamak', 'İki ürünün aynı molekül olmasını sağlamak', 'Yolu substrat düzeyinde fosforilasyona bağlamak'], 'Kısmi (birikimli) geri besleme, yalnız bir ürün bolken ortak basamağın hâlâ çalışıp diğer dalı beslemesine izin verir.'),
  ('Kan pıhtılaşmasında protrombinin trombine, trombinin de fibrinojeni fibrine dönüştürmesi gibi art arda etkinleşmeler hangi metabolik ilkeye örnektir?', 'Basamaklı yükseltme', ['Geri dönüşümsüz yarışmalı inhibisyon', 'Substrat düzeyinde fosforilasyon', 'Glikolizle enerji üretimi'], 'Her etkin enzim bir sonraki enzimin çok sayıda molekülünü etkinleştirir; küçük bir başlangıç sinyali çok büyük bir yanıta dönüşür.'),
  ('Karaciğerdeki glukokinazın Km değeri kas heksokinazınınkinden çok yüksektir. Bu fark karaciğere hangi işlevsel avantajı sağlar?', 'Kan şekeri yüksekken fazla glikozu yakalayıp depolar, düşükken glikozu kaslara bırakır.', ['Açlıkta kan glikozunu kaslardan daha hızlı tüketir.', 'Karaciğerin glikozu hiç fosforlayamamasını sağlar.', 'Kasların glikojen depolamasını tamamen engeller.'], 'Yüksek Km\'li glukokinaz ancak glikoz bolken hızlı çalışır; düşük Km\'li heksokinaz ise düşük derişimde bile kas ve beyne glikoz almayı sürdürür.'),
  ('Enzim deneylerinde tepkime hızının genellikle ilk dakikalardaki ürün artışından (başlangıç hızı) ölçülmesinin nedeni nedir?', 'Bu sürede substrat derişimi neredeyse değişmez ve ürün birikimi etkisizdir.', ['Enzimler yalnız ilk dakikalarda etkindir.', 'İlk dakikalarda sıcaklık her zaman en yüksektir.', 'Sonraki dakikalarda enzim tamamen ürüne dönüşür.'], 'Başlangıç hızı, bilinen substrat derişimine karşılık gelen hızı verir; sonra substrat azalır ve ürün geri tepkimeyi ya da inhibisyonu etkileyebilir.'),
  ('Bir enzim çözeltisine yüksek derişimde üre eklendiğinde enzim etkinliğini yitiriyor, üre diyalizle uzaklaştırılınca etkinliğin bir kısmı geri geliyor. Christian Anfinsen\'in benzer deneylerle ulaştığı sonuç neydi?', 'Proteinin doğru üç boyutlu biçimi amino asit dizisinde kodlanmıştır.', ['Enzimler bir kez bozulunca asla eski biçimine dönemez.', 'Enzimlerin biçimi yalnız ortamın sıcaklığına bağlıdır.', 'Üre enzimlerin substratıdır.'], 'Anfinsen ribonükleazla, bozulan proteinin denatüran uzaklaştırılınca kendiliğinden doğru katlanabildiğini gösterdi; biçimi belirleyen birincil dizidir.'),
  ('Gliseraldehit-3-fosfat dehidrogenaz basamağında ATP harcanmadan substrata eklenen fosfatın kaynağı nedir?', 'Ortamdaki inorganik fosfat', ['ATP\'nin uç fosfatı', 'NADH\'nin fosfatı', 'Pirüvattan koparılan fosfat'], 'Bu basamakta yükseltgenmeden açığa çıkan enerji, inorganik fosfatın yüksek enerjili bir bağla bağlanmasına harcanır.'),
  ('Krebs döngüsünün ara ürünü olan sitratın sitoplazmada birikmesi fosfofruktokinazı baskılar. Bu düzenlemenin mantığı nedir?', 'Krebs döngüsü doyduğunda glikolizin de yavaşlatılması', ['Sitratın glikoliz yerine fotosentezde kullanılması', 'Sitratın glikozla doğrudan tepkimeye girmesi', 'Fosfofruktokinazın sitratı substrat olarak kullanması'], 'Sitrat birikmesi Krebs döngüsünün yeterince beslendiğini gösterir; yolun başındaki enzim baskılanarak arz ve talep dengelenir.'),
  ('Arsenat, glikolizde gliseraldehit-3-fosfat dehidrogenaz basamağında inorganik fosfatın yerine geçebilir ve oluşan ürün kendiliğinden hidrolize olur. Bu durumda glikoz başına net ATP kazancı için ne beklenir?', 'Fosfogliserat kinaz basamağı atlandığı için net kazanç sıfıra düşer.', ['Net kazanç iki katına çıkar, çünkü arsenat ek enerji taşır.', 'Net kazanç değişmez, çünkü arsenat yalnız NADH oluşumunu etkiler.', 'Glikoliz tamamen durur ve hiç pirüvat oluşmaz.'], '1,3-bisfosfogliserat yerine oluşan kararsız ürün ATP vermeden parçalanır; o basamağın 2 ATP\'si kaybolur ve 4−2−2 = 0 net ATP kalır, ancak pirüvat oluşmaya devam eder.'),
  ('Hızla bölünen pek çok kanser hücresi, oksijen bol olsa bile glikozu yoğun biçimde laktata çevirir. Bu gözleme ne ad verilir?', 'Warburg etkisi', ['Pasteur etkisi', 'Emerson etkisi', 'Bohr etkisi'], 'Otto Warburg 1920\'lerde tümör hücrelerinin oksijen varlığında da yüksek glikoliz yaptığını gözlemledi; PET taramaları bu yüksek glikoz alımından yararlanır.'),
  ('Pirüvat dehidrogenaz kompleksinin, ürünleri olan asetil-KoA ve NADH birikince yavaşlaması neyi sağlar?', 'Hücrenin ihtiyaç duymadığı karbonun gereksiz yere yakılmasını önler.', ['Glikolizin oksijensiz ortamda tamamen durmasına yol açar.', 'Krebs döngüsünün hiç durmadan sürekli en yüksek hızda dönmesini sağlar.', 'Fazla pirüvatın kloroplastlara taşınarak orada depolanmasını sağlar.'], 'Ürün birikmesi enerji ve yakıtın yeterli olduğunu gösterir; kompleksin baskılanması pirüvatın glikoz yapımı gibi başka yollara kalmasını sağlar.'),
  ('Hayvanlarda asetil-KoA\'nın glikoza dönüştürülememesinin nedeni nedir?', 'Pirüvattan asetil-KoA oluşumu geri dönüşümsüzdür.', ['Asetil-KoA hücre içinde hiç bulunmadığı için tepkimeye giremez.', 'Asetil-KoA yalnız kloroplastlarda ve yalnız ışıkta üretilebilir.', 'Asetil-KoA altı karbonlu olup glikozdan daha büyük bir moleküldür.'], 'Pirüvat dehidrogenaz tepkimesi tersine işlemez ve hayvanlarda glioksilat döngüsü yoktur; bu yüzden yağ asitlerinden net glikoz üretilemez.'),
  ('Krebs döngüsünde süksinatın yükseltgenmesinde NAD⁺ yerine FAD kullanılmasının nedeni nedir?', 'Bu tepkimede açığa çıkan enerjinin NAD⁺\'yı indirgemeye yetmemesi', ['FAD\'nin hücrede NAD⁺\'dan çok daha bol bulunması', 'Süksinatın yalnız kloroplastta yükseltgenebilmesi', 'FAD\'nin ATP sentezini doğrudan yapabilmesi'], 'Süksinattan fumarat oluşumunun serbest enerji değişimi NAD⁺\'yı indirgemek için yetersizdir; daha yüksek potansiyelli FAD kullanılır.'),
  ('Krebs döngüsü moleküler oksijeni doğrudan kullanmadığı hâlde oksijensiz koşulda durur. Bunun nedeni nedir?', 'NADH ve FADH₂ yükseltgenemediği için NAD⁺ ve FAD tükenir.', ['Oksijen döngüdeki her enzimin substratıdır ve her basamakta harcanır.', 'Oksijensizlikte mitokondri matriksi doğrudan sitoplazmayla birleşir.', 'Oksijensiz ortamda oksaloasetat hemen yağ asidine dönüşür.'], 'Taşıyıcılar ancak ETS\'de oksijene elektron verince yeniden yükseltgenir; oksijen yoksa yükseltgenmiş taşıyıcı kalmaz ve dehidrogenazlar durur.'),
  ('Krebs döngüsü ara ürünlerinin amino asit ve porfirin gibi moleküllerin sentezi için döngüden çekilmesi, döngünün hangi özelliğini gösterir?', 'Hem yıkım hem yapım yollarına hizmet eden amfibolik bir yol olduğunu', ['Yalnızca yıkım tepkimelerine hizmet eden bir yol olduğunu', 'Yalnızca bitki hücrelerinde çalışan bir yol olduğunu', 'Ara ürünlerinin hiçbir zaman eksilmediğini'], 'Krebs döngüsü hem enerji üretir hem de biyosentez için öncül sağlar; bu iki yönlü role amfibolik denir.'),
  ('Krebs ara ürünleri biyosentez için çekildiğinde döngünün durmaması için pirüvattan oksaloasetat üreten tepkimeye ne ad verilir?', 'Doldurucu (anaplerotik) tepkime', ['Fotorespirasyon', 'Geri besleme inhibisyonu', 'Oksidatif deaminasyon'], 'Pirüvat karboksilaz, pirüvata CO₂ ekleyerek oksaloasetat üretir; bu, döngüden eksilen ara ürünleri yerine koyar.'),
  ('Elektron taşıma zincirinde Kompleks III\'ü engelleyen antimisin A eklenirse hangi taşıyıcı büyük ölçüde indirgenmiş hâlde birikir?', 'Ubikinon', ['Sitokrom c', 'Oksijen', 'Sitokrom c oksidaz'], 'Engelin öncesindeki taşıyıcılar elektronlarını veremez ve indirgenmiş kalır; sonrasındakiler ise yükseltgenmiş hâle geçer.'),
  ('Rotenon adlı balık zehri Kompleks I\'i engeller. Rotenonla muamele edilmiş izole mitokondrilere süksinat verilirse ne beklenir?', 'Oksijen tüketimi ve ATP üretimi bir ölçüde sürer.', ['Oksijen tüketimi hemen tamamen durur ve hiç ATP oluşmaz.', 'Mitokondriler glikozu doğrudan sitokrom c\'ye çevirmeye başlar.', 'Rotenon etkisi kalkar ve Kompleks I yeniden çalışır.'], 'Süksinat elektronlarını Kompleks II üzerinden zincire verir ve engellenen Kompleks I atlanır; zincirin geri kalanı çalışmayı sürdürür.'),
  ('Proton itici güç (proton motive force) hangi iki bileşenden oluşur?', 'Proton derişim (pH) farkı ve zarın iki yanındaki elektriksel yük farkı', ['Glikoz derişim farkı ve su basıncı', 'Oksijen basıncı ve karbondioksit basıncı', 'ATP derişimi ve ADP derişimi'], 'Protonların bir yanda birikmesi hem pH farkı hem de pozitif yük birikiminden kaynaklanan zar potansiyeli oluşturur.'),
  ('Jagendorf ve Uribe 1966\'da kloroplast tilakoitlerini karanlıkta önce pH 4\'lük ortamda bekletip sonra pH 8\'lik ADP ve fosfatlı ortama aldıklarında ATP oluştuğunu gördüler. Bu deney neyi kanıtlar?', 'Yalnız proton farkının, ışık ve elektron akışı olmadan ATP sentezine yettiğini', ['Işığın ATP üretimi için kesinlikle şart olduğunu', 'Tilakoitlerin karanlıkta glikoz ürettiğini', 'ATP sentezinin pH\'tan tamamen bağımsız olduğunu'], 'Tilakoit içi asidik, dışı bazik hâle getirildiğinde ışık olmadan ATP sentezlendi; bu, kemiozmotik kuramı güçlü biçimde destekledi.'),
  ('ATP sentazın \'dönen moleküler motor\' olarak çalıştığını gösteren çalışmalar hangi sonucu ortaya koymuştur?', 'Protonların akışı bir rotoru döndürür ve dönme katalitik alt birimlerin biçimini sırayla değiştirerek ATP yaptırır.', ['ATP sentaz hiç hareket etmeden yalnız ışık soğurur.', 'ATP sentaz protonları matriksten zarlar arası boşluğa pompalayarak ATP yapar.', 'ATP sentazın her alt birimi farklı bir besin molekülünü yıkar.'], 'Boyer\'in bağlanma değişimi mekanizması ve Walker\'ın yapı çalışmaları (1997 Nobel) dönme katalizini gösterdi.'),
  ('ATP sentaz, ortamda proton farkı yokken ATP bolsa ters yönde çalışabilir. Bu durumda ne yapar?', 'ATP\'yi hidrolize ederek protonları zar boyunca pompalar.', ['Elektronları oksijene aktararak su yapar.', 'Glikozu pirüvata çevirir.', 'Işık enerjisini soğurup ATP sentezler.'], 'Enzim tersinirdir; bakterilerde bu ters işleyiş zar potansiyelini korumak için kullanılabilir.'),
  ('Oligomisin adlı antibiyotik ATP sentazın proton kanalını tıkar. Sağlam mitokondrilere oligomisin eklenince oksijen tüketimine ne olur?', 'Büyük ölçüde azalır, çünkü proton farkı artıp elektron akışını yavaşlatır.', ['Artar, çünkü elektronlar artık daha serbestçe oksijene akar.', 'Hiç değişmez, çünkü ETS ile ATP sentaz birbirinden bağımsızdır.', 'Oksijen yerine karbondioksit tüketilmeye başlanır.'], 'Protonlar geri akamayınca fark çok büyür ve pompaların çalışması zorlaşır; ETS ile ATP sentezi sıkıca eşleşmiş olduğu için oksijen tüketimi de düşer.'),
  ('Mitokondrinin ATP sentezinde kullandığı ADP\'yi sitoplazmadan alıp ürettiği ATP\'yi dışarı vermesini sağlayan iç zar proteini hangisidir?', 'ADP/ATP çevirici', ['Sodyum-potasyum pompası', 'Akuaporin', 'Glikoz taşıyıcısı GLUT1'], 'Bu karşıt taşıyıcı bir ATP\'yi dışarı verirken bir ADP\'yi içeri alır; iç zar adenin nükleotitlerine kendiliğinden geçirgen değildir.'),
  ('Bir mitokondriye fazladan ADP verildiğinde oksijen tüketiminin hemen artması ne ile açıklanır?', 'ATP sentazın hızlanıp proton farkını azaltması ve elektron akışının hızlanması', ['ADP\'nin oksijenle doğrudan tepkimeye girmesi', 'ADP\'nin Kompleks IV\'ü kalıcı olarak etkinleştirmesi', 'ADP\'nin glikoz yerine yakıt olarak yakılması'], 'Bu \'solunum denetimi\'dir: ADP varken ATP sentaz protonları geri akıtır, fark azalır ve ETS daha hızlı çalışabilir.'),
  ('Kloroplast ve mitokondride ATP sentazın matris ya da stromaya bakan katalitik başlıklarının ortak yönü için hangisi doğrudur?', 'İkisinde de ATP, protonların düşük derişimli olduğu bölmeye bakan yüzde üretilir.', ['İkisinde de ATP zarlar arası boşlukta üretilir.', 'Mitokondride stromada, kloroplastta matrikste üretilir.', 'İkisinde de ATP tilakoit boşluğunda üretilir.'], 'Protonlar mitokondride zarlar arası boşlukta, kloroplastta tilakoit boşluğunda birikir; ATP sentaz başlığı sırasıyla matrikse ve stromaya bakar.'),
  ('1930\'larda zayıflama ilacı olarak satılan 2,4-dinitrofenol (DNP) birçok ölüme yol açınca yasaklanmıştır. DNP\'nin tehlikeli olmasının temel nedeni nedir?', 'Protonları iç zardan geri taşıyarak enerjinin ATP yerine ısıya dönüşmesine yol açması', ['Oksijenin akciğerlerden kana geçişini tamamen engellemesi', 'Glikozu doğrudan yağa dönüştürerek damarları tıkaması', 'Kandaki alyuvarları hızla parçalayarak oksijen taşınmasını bitirmesi'], 'DNP bir ayırıcıdır: proton farkını ATP sentaz dışından boşaltır, besinler hızla yakılır ama ATP az üretilir ve vücut ısısı tehlikeli düzeye çıkabilir.'),
  ('Ayırıcı bir madde verilen bir hücrede ETS\'nin oksijen tüketim hızına ne olur?', 'Artar, çünkü proton farkı azaldığı için elektron akışı frenlenmez.', ['Sıfıra iner, çünkü ayırıcı elektronları kendisi tutar.', 'Değişmez, çünkü oksijen tüketimi yalnız glikolize bağlıdır.', 'Azalır, çünkü ayırıcı ADP\'yi ortamdan uzaklaştırır.'], 'Proton farkı sürekli boşaldığı için pompalar karşı direnç görmez; elektron akışı ve oksijen tüketimi hızlanır, ATP ise az üretilir.'),
  ('Kokarca lahanası gibi bazı bitkilerin çiçek bölgesini çevre sıcaklığının 15–20 °C üzerine ısıtabilmesi hangi metabolik özellikle ilgilidir?', 'Solunumun büyük kısmının ATP üretmeyen alternatif oksidaz yolundan yürütülmesi', ['Fotosentezin karanlıkta da yüksek hızla sürdürülmesi', 'Hücrelerin glikozu hiç yıkmadan depolaması', 'Kloroplastların ısıyı güneşten depolayıp gece salması'], 'Bu bitkilerde elektronlar proton pompalayan komplekslerin bir kısmını atlayıp alternatif oksidazla oksijene geçer; enerji ısı olarak açığa çıkar.'),
  ('Bir NADH ≈ 2,5 ATP ve bir FADH₂ ≈ 1,5 ATP kabul edilirse Krebs döngüsünün tek bir dönüşünde oluşan indirgenmiş taşıyıcılardan oksidatif fosforilasyonla kaç ATP elde edilir?', '9', ['10', '7,5', '12'], '3 NADH × 2,5 = 7,5; 1 FADH₂ × 1,5 = 1,5; toplam 9 ATP.'),
  ('Eski ders kitaplarında bir glikozdan 36–38 ATP, yeni kaynaklarda ise yaklaşık 30–32 ATP elde edildiği yazar. Bu farkın temel nedeni nedir?', 'Ölçümlerin NADH ve FADH₂ başına daha az ATP oluştuğunu ve taşıma maliyetlerini göstermesi', ['Günümüz insanlarının mitokondrilerinin evrimle değişmiş olması', 'Glikozun yapısının ölçüm yöntemine göre değişmesi', 'Eski hesaplarda glikolizin hiç dikkate alınmaması'], 'Eskiden NADH için 3, FADH₂ için 2 ATP varsayılıyordu; proton sayılarının ölçülmesi ve fosfat ile ADP taşınmasının da proton gerektirmesi değerleri 2,5 ve 1,5\'e indirdi.'),
  ('Glikoliz sırasında sitoplazmada oluşan NADH, mitokondri iç zarından doğrudan geçemez. Bu NADH\'nin elektronları matrikse nasıl aktarılır?', 'Mekik sistemleriyle elektronlar başka moleküllere aktarılarak', ['NADH\'nin önce glikoza dönüştürülmesiyle', 'Elektronların doğrudan oksijenle sitoplazmada su yapmasıyla', 'NADH\'nin çekirdek zarındaki porlardan geçmesiyle'], 'Gliserol-3-fosfat ve malat-aspartat mekikleri, sitoplazmik NADH\'nin elektronlarını iç zardan geçebilen moleküller aracılığıyla taşır.'),
  ('Gliserol-3-fosfat mekiğinin kullanıldığı hücrelerde, sitoplazmik NADH\'nin verdiği ATP neden daha azdır?', 'Elektronlar matriksteki NAD⁺ yerine FAD\'ye aktarılır.', ['Elektronlar mitokondriye hiç ulaşamaz.', 'Bu mekik her elektron için iki ATP harcar.', 'Elektronlar doğrudan karbondioksite aktarılır.'], 'Bu mekikte elektronlar iç zardaki bir FAD\'ye geçer ve ubikinon düzeyinde zincire girer; bu nedenle NADH başına yaklaşık 1,5 ATP elde edilir.'),
  ('Bir mol glikozun yanmasıyla yaklaşık 2870 kJ enerji açığa çıkar. Bir mol ATP\'nin hidrolizi hücrede yaklaşık 30,5 kJ veriyorsa ve glikoz başına 32 ATP üretiliyorsa enerji dönüşüm verimi yaklaşık yüzde kaçtır?', '34', ['24', '50', '68'], '32 × 30,5 = 976 kJ; 976 / 2870 ≈ 0,34, yani yaklaşık %34. Geri kalan enerji ısı olarak açığa çıkar.'),
  ('Glikozun tamamen yükseltgenmesinde oluşan 10 NADH ve 2 FADH₂\'den, NADH = 2,5 ve FADH₂ = 1,5 ATP alınarak kaç ATP elde edilir?', '28', ['25', '30', '32'], '10 × 2,5 = 25; 2 × 1,5 = 3; toplam 28 ATP. Buna substrat düzeyindeki 4 ATP eklenince 32 ATP bulunur.'),
  ('Nitratı son elektron alıcısı olarak kullanan anaerobik solunumda oksijenli solunuma göre daha az ATP üretilmesinin nedeni nedir?', 'Nitratın indirgenme potansiyelinin oksijenden düşük olması nedeniyle elektronların daha az enerji vermesi', ['Nitratın hücre zarından hiç geçememesi', 'Bu canlıların glikolizi hiç yapamaması', 'Nitratın her seferinde ATP harcanarak alınması'], 'Elektronların düştüğü \'enerji basamağı\' son alıcının indirgenme potansiyeline bağlıdır; oksijen en güçlü alıcı olduğundan en çok enerjiyi o sağlar.'),
  ('Tripalmitin adlı yağın yanma tepkimesi 2 C₅₁H₉₈O₆ + 145 O₂ → 102 CO₂ + 98 H₂O biçimindedir. Bu yağın solunum katsayısı yaklaşık kaçtır?', '0,70', ['1,00', '0,80', '1,42'], 'RQ = 102 / 145 ≈ 0,70. Yağlar oksijence fakir olduğundan yakılmaları için görece çok O₂ gerekir.'),
  ('16 karbonlu palmitik asidi sekiz asetil-KoA\'ya ayırmak için kaç beta oksidasyon turu gerekir?', '7', ['8', '16', '6'], 'Son tur dört karbonlu parçayı iki asetil-KoA\'ya ayırdığı için tur sayısı asetil-KoA sayısından bir eksiktir: 8 − 1 = 7.'),
  ('Yağ asidi sentezi ile beta oksidasyon karşılaştırıldığında hangisi doğrudur?', 'Sentez sitoplazmada NADPH ile, yıkım mitokondride NAD⁺ ve FAD ile olur.', ['İkisi de mitokondride ve aynı enzimlerle gerçekleşir.', 'Sentez oksijen tüketir, yıkım ise oksijen üretir.', 'Sentez yalnız bitkilerde gerçekleşir; yıkım ise yalnız hayvan hücrelerinde, lizozomlarda görülür.'], 'Yapım ve yıkım yollarının ayrı bölmelerde ve farklı taşıyıcılarla yürümesi, ikisinin aynı anda boşa dönmesini önler.'),
  ('Glikoza dönüştürülebilen amino asitler (glukojenik) ile yalnız keton cisimciğine dönüştürülebilenler (ketojenik) arasındaki fark neye dayanır?', 'İskeletin pirüvata ya da Krebs ara ürününe mi, yalnız asetil-KoA\'ya mı dönüştüğüne', ['Amino asidin bitkisel mi yoksa hayvansal mı bir besin kaynağından alındığına', 'Amino asidin kaç tane amino grubu taşıdığına', 'Amino asidin hücrede sentezlenip sentezlenmediğine'], 'Asetil-KoA hayvanlarda glikoza çevrilemez; iskeleti yalnız asetil-KoA\'ya giden lösin ve lizin ketojeniktir.'),
  ('Glukoneogenez glikolizin tam tersi değildir. Bunun temel nedeni nedir?', 'Glikolizin geri dönüşümsüz üç basamağı başka enzimlerle atlanır.', ['Glukoneogenez yalnız kloroplastlarda ve yalnızca ışıklı ortamda gerçekleşir.', 'Glukoneogenezde hiç enzim kullanılmaz.', 'Glukoneogenez glikozu değil, yalnız yağ asidini üretir.'], 'Heksokinaz, fosfofruktokinaz ve pirüvat kinaz basamakları çok ekzergoniktir; glukoneogenez bunları farklı enzimlerle ve ek enerji harcayarak aşar.'),
  ('Kas hücreleri glikojenlerini yıkıp kana glikoz veremezken karaciğer bunu yapabilir. Bu farkın nedeni nedir?', 'Kas hücrelerinde glikoz-6-fosfataz enziminin bulunmaması', ['Kas hücrelerinde hiç glikojen bulunmaması ve depolanmaması', 'Karaciğerin glikojeni oksijensiz ortamda depolaması', 'Kas glikojeninin selüloz yapısında olması'], 'Fosfat grubunu glikoz-6-fosfattan koparan glikoz-6-fosfataz karaciğerde bulunur; kasta glikoz fosforlu kaldığı için hücreden çıkamaz ve kasın kendi işine harcanır.'),
  ('Glikojen fosforilaz enziminin glikojeni su yerine inorganik fosfatla parçalamasının hücreye yararı nedir?', 'Glikoz-1-fosfatın ATP harcanmadan fosforlu elde edilmesi', ['Glikozun hücre dışına hemen ve kendiliğinden, taşıyıcı gerekmeden çıkabilmesi', 'Glikojenin selüloza dönüştürülebilmesi', 'Enzimin hiç substrata bağlanmadan çalışabilmesi'], 'Fosforoliz sayesinde glikoz zaten fosforlanmış olarak çıkar; glikolize girerken heksokinaz basamağındaki ATP harcanmaz.'),
  ('Glikoz yerine glikozun öncüsü olarak glukoneogenezle yeniden kullanılabilen gliserol ve laktat varken yağ asitlerinin hayvanlarda bu amaçla kullanılamamasının sonucu nedir?', 'Uzun açlıkta glikoz için proteinlerin de yıkılması', ['Hayvanların vücutlarında hiçbir koşulda yağ depolayamaması', 'Yağ asitlerinin hiçbir koşulda yakılamaması', 'Beynin yalnızca yağ asidi kullanması'], 'Yağ asitlerinden gelen asetil-KoA glikoza çevrilemez; beynin glikoz ihtiyacı açlıkta kısmen kas proteinlerinin yıkımıyla karşılanır.'),
  ('Pentoz fosfat yolunun en etkin olması beklenen hücre hangisidir?', 'Yağ asidi ve steroit sentezleyen bir yağ dokusu hücresi', ['Uzun süredir bölünmeyen ve neredeyse hiç sentez yapmayan bir hücre', 'Yalnız glikoliz yapan olgun bir kemik hücresi', 'Fotosentez yapan bir bitki hücresinin tilakoit zarı'], 'Yağ asidi ve steroit sentezi çok NADPH gerektirir; bu nedenle karaciğer, yağ dokusu ve böbrek üstü korteksinde yol çok etkindir.'),
  ('Glikoz-6-fosfat dehidrogenaz eksikliğinde alyuvarların yükseltgen hasara karşı korunmasız kalmasının nedeni nedir?', 'Glutatyonu indirgenmiş tutacak NADPH\'nin yetersiz kalması', ['Alyuvarların glikozu hiçbir taşıyıcıyla hücre içine alamaması', 'Alyuvarların mitokondrilerinin çoğalması', 'Hemoglobinin glikoza dönüşmesi'], 'Pentoz fosfat yolunun ilk enzimi eksik olunca NADPH azalır; indirgenmiş glutatyon tükenir ve oksitleyici maddeler alyuvar zarını bozar.'),
  ('Bir kişi günde 2500 kcal alıp 2000 kcal harcıyor. 1 g yağ dokusunun yaklaşık 7,7 kcal enerjiye karşılık geldiği kabul edilirse bu fazlalık 30 günde yaklaşık kaç gram yağ dokusu birikimine yol açar?', 'Yaklaşık 1950 g', ['Yaklaşık 650 g', 'Yaklaşık 3900 g', 'Yaklaşık 15000 g'], 'Günlük fazla 500 kcal × 30 = 15000 kcal; 15000 / 7,7 ≈ 1948 g.'),
  ('Ruben ve Kamen deneyinde yalnız CO₂\'nin oksijeni ¹⁸O ile işaretlenmiş olsaydı işaretin en çok hangi ürünlerde görülmesi beklenirdi?', 'Şeker ve suda', ['Yalnız açığa çıkan oksijen gazında', 'Klorofil molekülünün magnezyum atomunda', 'Hiçbir üründe görülmezdi'], 'CO₂\'nin oksijenleri şeker ve fotosentezde oluşan suya geçer; O₂ ise suyun oksijeninden gelir.'),
  ('Robert Hill 1937\'de izole kloroplastlara CO₂ vermeden, yalnız demir tuzu gibi bir elektron alıcısı ekleyerek ışıkta oksijen çıkışı elde etti. Bu deney neyi göstermiştir?', 'Oksijen çıkışının CO₂ bağlanmasından ayrı yürüyebildiğini', ['Kloroplastların CO₂ olmadan da bol miktarda glikoz üretebildiğini', 'Oksijenin demir tuzundan geldiğini', 'Işığın fotosentezde gereksiz olduğunu'], 'Hill tepkimesi, suyun ışıkla yükseltgenip O₂ çıkmasının şeker yapımından bağımsız yürüyebildiğini gösterdi.'),
  ('Calvin deneyinde ışık kapatıldığında RuBP\'nin hızla azalıp PGA\'nın birikmesi nasıl açıklanır?', 'CO₂ bağlanması sürer ama ATP ve NADPH tükendiği için PGA ileriye işlenemez.', ['Işık kapanınca rubisko doğrudan PGA\'yı RuBP\'ye çevirir ve döngü tersine döner.', 'Karanlıkta CO₂ hiç bağlanamaz.', 'PGA ışıkta yıkılır, karanlıkta yeniden sentezlenir.'], 'Karanlıkta RuBP tüketilip PGA\'ya çevrilir; ancak PGA\'nın G3P\'ye indirgenmesi ve RuBP\'nin yenilenmesi ATP ve NADPH gerektirdiğinden döngü tıkanır.'),
  ('Calvin deneyinde ışık açık tutulup ortamdaki CO₂ aniden kesilirse RuBP ve PGA miktarları nasıl değişir?', 'RuBP birikir, PGA azalır.', ['RuBP azalır, PGA birikir.', 'İkisi de aynı anda artar.', 'İkisi de hiç değişmeden kalır.'], 'CO₂ olmadan RuBP tüketilemez ama ışık enerjisiyle yenilenmeye devam eder; PGA ise üretilmediği hâlde işlenmeyi sürdürdüğü için azalır.'),
  ('Klorofil çözeltisi beyaz ışıkla aydınlatıldığında kırmızı renkte bir ışıma (floresans) yaptığı gözlenir. Bunun nedeni nedir?', 'Uyarılmış elektronların enerjiyi ışık olarak geri vermesi', ['Klorofilin kırmızı ışığı hiçbir koşulda soğuramaması ve yansıtması', 'Çözeltinin içinde hemen glikoz sentezlenmesi', 'Klorofilin ışıkta demire dönüşmesi'], 'Zardan ayrılmış klorofilde uyarılmış elektronlar elektron taşıyıcılarına geçemez; temel duruma dönerken enerji ısı ve kırmızı ışık olarak salınır.'),
  ('Emerson\'un deneylerinde 680 nm\'nin üzerindeki uzak kırmızı ışıkla fotosentez verimi düştü, ancak buna daha kısa dalga boylu ışık eklenince verim iki ışığın ayrı ayrı etkilerinin toplamını aştı. Bu \'Emerson artış etkisi\' neyi gösterir?', 'İki ayrı fotosistemin birlikte çalıştığını', ['Klorofilin yalnız uzak kırmızı ışığı soğurduğunu', 'Fotosentezin ışıktan tamamen bağımsız bir süreç olduğunu', 'Karotenoitlerin fotosentezi engellediğini'], 'Uzak kırmızı ışık ağırlıkla bir fotosistemi uyarır; iki fotosistem birlikte uyarıldığında elektron akışı çok daha verimli olur.'),
  ('Kalvin döngüsü glikoz başına NADPH\'ye oranla daha fazla ATP gerektirir. Kloroplast bu dengesizliği nasıl giderir?', 'Devirli elektron akışıyla ek ATP üreterek', ['Fazla NADPH\'yi doğrudan ATP\'ye dönüştürerek', 'Mitokondriden NADPH alarak', 'Kalvin döngüsünü karanlıkta çalıştırarak'], 'Kalvin döngüsü her CO₂ için 3 ATP ve 2 NADPH ister; devirsiz akışın oranı bunu karşılamaz, devirli akış yalnız ATP üreterek açığı kapatır.'),
  ('Bitkileri öldüren diuron (DCMU) adlı ot ilacı, fotosistem II\'den plastokinona elektron aktarımını engeller. Bu maddeyle muamele edilen yaprakta hangisi beklenir?', 'Oksijen çıkışı ve NADPH üretimi durur.', ['Oksijen çıkışı çok artar, NADPH üretimi ise hiç değişmeden sürer.', 'Kalvin döngüsü ışıktan bağımsız hızlanır.', 'Fotosistem II elektronlarını doğrudan NADP⁺\'ya verir.'], 'PSII\'den elektron çıkamazsa su parçalanması ve devirsiz akış durur; PSI\'e elektron gitmediği için NADPH da üretilemez.'),
  ('Parakuat adlı ot ilacı fotosistem I\'den elektron çalıp oksijene verir. Bu ilacın bitki hücresine zararı nereden kaynaklanır?', 'Zarları bozan reaktif oksijen türlerinin oluşması', ['Klorofilin hemen ve tamamen glikoza dönüşmesi', 'Kloroplastların aniden mitokondriye dönüşmesi', 'Suyun fotolizinin hızlanıp fazla su üretilmesi'], 'Elektronlar oksijene aktarılınca süperoksit gibi radikaller oluşur; bunlar zar lipitlerini ve proteinleri hızla bozar.'),
  ('P680⁺\'nın canlılarda bilinen en güçlü biyolojik yükseltgenlerden biri olmasının fotosentezdeki önemi nedir?', 'Sudan elektron koparabilecek güçte olması', ['Glikozu ışık olmadan yakabilmesi', 'Oksijeni suya indirgeyebilmesi', 'CO₂\'yi doğrudan ve tek basamakta glikoza dönüştürebilmesi'], 'Su çok kararlı bir moleküldür; ondan elektron alabilmek için P680⁺ kadar yüksek indirgenme potansiyeli gerekir.'),
  ('Kalvin döngüsünde üç CO₂ bağlandığında oluşan altı G3P\'den kaçı döngüde RuBP\'nin yenilenmesine harcanır?', '5', ['3', '1', '6 molekülün tamamı'], 'Altı G3P\'den beşi (15 karbon) üç RuBP\'yi (3 × 5 = 15 karbon) yeniden oluşturur; biri net ürün olarak döngüden çıkar.'),
  ('Kalvin döngüsünün \'ışıktan bağımsız tepkimeler\' olarak anılmasına karşın gece büyük ölçüde durmasının nedenlerinden biri hangisidir?', 'Rubisko gibi enzimlerin ışıkla oluşan stroma koşullarında etkinleşmesi', ['Karanlıkta stromadaki bütün CO₂\'nin donup hareketsiz kalması ve enzimlere bağlanamaması', 'Gece kloroplastların tamamen hücreden atılması', 'Döngü enzimlerinin yalnız güneş ısısıyla çalışabilmesi'], 'Işıkta stroma pH\'ı yükselir, Mg²⁺ derişimi artar ve ferredoksin-tiyoredoksin sistemi enzimleri etkinleştirir; karanlıkta bu enzimler kapanır.'),
  ('Rubisko enziminin dünyadaki en bol protein olduğu kabul edilir. Bu bolluğun nedenlerinden biri hangisidir?', 'Katalitik hızı çok düşük olduğu için çok üretilmesinin gerekmesi', ['Hayvanların da kaslarında bu enzimi bol miktarda sentezleyip depolaması', 'Rubiskonun aynı zamanda hücre duvarının yapı maddesi olması', 'Rubiskonun hiç yıkılmadan sonsuza kadar kalması'], 'Rubisko saniyede yalnız birkaç CO₂ bağlar; yeterli fotosentez için yaprak proteinlerinin büyük bölümü rubisko olarak üretilir.'),
  ('Bir glikoz molekülünün sentezi için Kalvin döngüsünde toplam kaç ATP ve kaç NADPH harcanır?', '18 ATP ve 12 NADPH', ['12 ATP ve 18 NADPH', '6 ATP ve 6 NADPH', '36 ATP ve 6 NADPH molekülü'], 'Her CO₂ için 3 ATP ve 2 NADPH gerekir; 6 CO₂ için 18 ATP ve 12 NADPH harcanır.'),
  ('Fotosentezin dengelenmiş denklemi 6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂ + 6H₂O biçiminde de yazılır. Girenlerde 12 su gösterilmesinin nedeni nedir?', '6 O₂\'deki 12 oksijen atomunun tamamının sudan gelmesi', ['Glikozun yapısında 12 su molekülünün bozulmadan, olduğu gibi bulunması', 'Klorofilin her ışık tepkimesinde suyla yer değiştirmesi', 'Bitkinin 6 suyu köklerinden geri salması'], '6 O₂ için 12 oksijen atomu gerekir ve bunlar yalnız sudan gelir; CO₂\'nin oksijenleri ise glikoz ve yeni oluşan suya geçer.'),
  ('Fotosentezle üretilen glikozdaki karbon, hidrojen ve oksijen atomlarının kaynakları hangi seçenekte doğru verilmiştir?', 'C ve O: CO₂\'den; H: sudan', ['C: CO₂\'den; H ve O: sudan', 'C, H ve O: tamamen sudan', 'C: sudan; H: CO₂\'den; O: havadaki O₂\'den'], 'Glikozun karbonu ve oksijeni CO₂\'den, hidrojenleri ise sudan alınan elektron ve protonlardan gelir.'),
  ('Kalvin döngüsü glikoz başına 18 ATP harcar; devirsiz akış ise her NADPH için yaklaşık 1,3 ATP üretir. 12 NADPH üretilirken devirsiz akışla yaklaşık kaç ATP oluşur ve açık kaç ATP olur?', 'Yaklaşık 15,6 ATP; açık yaklaşık 2,4 ATP', ['Yaklaşık 18 ATP; herhangi bir açık oluşmaz', 'Yaklaşık 12 ATP; açık 6 ATP', 'Yaklaşık 24 ATP; 6 ATP fazlası vardır'], '12 × 1,3 ≈ 15,6 ATP; 18 − 15,6 ≈ 2,4 ATP açık devirli akışla kapatılır.'),
  ('Ilıman ve serin iklimlerde C3 bitkilerinin C4 bitkileriyle rahatça yarışabilmesi nasıl açıklanır?', 'Serinde fotorespirasyon az olduğundan C4\'ün ek maliyetinin karşılığını vermemesi', ['Serin iklimlerde C4 bitkilerinin yapraklarındaki klorofilin hiç ışık soğuramaması', 'C3 bitkilerinin serin iklimde rubisko kullanmayı bırakması', 'Serin havada PEP karboksilazın ürettiği şekerin donması'], 'Fotorespirasyon sıcakta belirginleşir; serin koşullarda C4\'ün CO₂ pompalama maliyeti kazancından fazla olabilir.'),
  ('Bir CAM bitkisinin yaprak özsuyunun asitliği gün boyunca ölçülürse hangi örüntü gözlenir?', 'Sabah erken en asidik, akşamüstü en az asidik', ['Öğlen saatlerinde en asidik, gece yarısı ise en az asidik', 'Gün boyunca hiç değişmez', 'Akşamüstü en asidik, sabah en az asidik'], 'Malik asit gece birikir ve sabaha en yüksek düzeydedir; gündüz CO₂ serbest bırakıldıkça asitlik azalır.'),
  ('CAM bitkilerinin büyüme hızlarının genellikle yavaş olmasının nedeni nedir?', 'Gece depolanan CO₂\'nin kofulun malik asit kapasitesiyle sınırlı olması', ['Gündüzleri yapraklarındaki pigmentlerin hiçbir dalga boyunda ışık soğuramaması', 'Kalvin döngüsünü yalnız gece yapabilmeleri', 'Fotosentezde oksijen yerine karbondioksit üretmeleri'], 'Gündüz kullanılacak CO₂ gece biriktirilebilen malik asitle sınırlıdır; bu, su tasarrufu karşılığında düşük toplam karbon kazancı demektir.'),
  ('Aynı ağacın güneş alan dış yaprakları ile gölgedeki iç yaprakları karşılaştırıldığında gölge yaprakları için genellikle hangisi doğrudur?', 'Daha ince ve geniştir, birim alanda daha çok klorofil b taşır.', ['Daha kalındır ve palizat dokusu çok katlıdır, bu nedenle daha çok ışık ister.', 'Hiç kloroplast taşımaz.', 'Stomaları sürekli kapalıdır.'], 'Gölge yaprakları az ışığı yakalamak için geniş ve incedir; ışık toplayıcı anten pigmentleri görece fazladır.'),
  ('Bir deneyde ışık şiddeti sabitken sıcaklık 10 °C\'den 20 °C\'ye çıkarıldığında fotosentez hızının çok az değiştiği gözleniyor. En olası yorum hangisidir?', 'Hızı sınırlayan etmen ışık şiddetidir.', ['Hızı sınırlayan etmen kesinlikle sıcaklıktır.', 'Bitkinin bütün enzimleri bozulmuştur.', 'Fotosentez sıcaklıktan hiçbir koşulda etkilenmez.'], 'Sıcaklık artışı hızı değiştirmiyorsa enzim tepkimeleri değil, ışığa bağlı tepkimeler sınırlayıcıdır; düşük ışıkta fotosentez sıcaklığa duyarsızdır.'),
  ('Kapalı, ışıklı bir kapta bulunan bir bitkinin ortamındaki CO₂ derişimi azalıp sonunda sabit bir değerde kalıyor. Bu sabit derişim için hangisi doğrudur?', 'Bitkinin fotosentez hızı solunum hızına eşit olmuştur.', ['Bitkinin fotosentezi tamamen durmuş, yalnız solunum sürmektedir.', 'Bitki ölmüştür.', 'Bitki CO₂ yerine oksijen bağlamaktadır.'], 'CO₂ azaldıkça fotosentez yavaşlar; solunumun CO₂ üretimiyle fotosentezin tüketiminin eşitlendiği derişime CO₂ telafi noktası denir.'),
  ('Kapalı kapta yan yana konan bir C3 ve bir C4 bitkisi uzun süre ışıkta tutulursa hangisi beklenir?', 'C4 bitkisi CO₂\'yi daha alta indirir; C3 bitkisi zamanla zarar görür.', ['C3 bitkisi CO₂\'yi tamamen sıfıra indirir ve bunun sonucunda C4 bitkisi kısa sürede ölür.', 'İki bitki de CO₂\'yi hiç değiştirmez.', 'İki bitki de aynı anda ölür.'], 'C4 bitkilerinin CO₂ telafi noktası çok düşüktür; C4 bitkisi C3\'ün net kazanç sağlayamayacağı düzeye kadar CO₂\'yi çeker.'),
  ('Cornelis van Niel\'in kükürt bakterileri üzerindeki çalışmaları bitkilerdeki fotosentez hakkında hangi öngörüye yol açmıştır?', 'Bitkilerdeki oksijenin sudan geldiği', ['Bitkilerin açığa çıkardığı oksijenin karbondioksitin parçalanmasından geldiği', 'Bitkilerin ışık olmadan da şeker yaptığı', 'Bitkilerin kükürt kullanarak fotosentez yaptığı'], 'Van Niel, CO₂ + 2H₂S → (CH₂O) + H₂O + 2S genellemesinden yola çıkarak bitkilerde H₂S yerine suyun bulunduğunu ve O₂\'nin sudan geldiğini öne sürdü.'),
  ('Bakteri klorofillerinin bitki klorofillerinden farklı olarak kızılötesine yakın dalga boylarını soğurabilmesi bu bakterilere hangi ekolojik avantajı sağlar?', 'Görünür ışığın tüketildiği derin katmanlarda yaşayabilmek', ['Gece ay ışığıyla da yüksek hızda fotosentez yaparak bütün rakiplerinden üstün gelmek', 'Oksijeni daha hızlı üretmek', 'Kükürt yerine su kullanabilmek'], 'Üstteki alg ve siyanobakteriler görünür ışığı soğurur; alttaki bakteriler geriye kalan kızılötesine yakın ışıkla fotosentez yapar.'),
  ('Kükürt bakterileri tarafından H₂S\'nin sülfata kadar yükseltgenmesi sonucunda ortamın pH\'ı nasıl değişir?', 'Sülfürik asit oluştuğu için düşer.', ['Amonyak açığa çıktığı için belirgin biçimde yükselir.', 'Hiç değişmez.', 'Önce yükselir sonra sabit kalır.'], 'Sülfat oluşumu ortamı asitleştirir; bazı kükürt bakterileri bu nedenle çok düşük pH\'ta yaşar ve maden atıklarının asitleşmesine katkıda bulunur.'),
  ('Baklagil köklerindeki nodüllerde bulunan bakterilerin azotu bağlayan nitrojenaz enzimi oksijene çok duyarlıdır. Nodüldeki leghemoglobinin görevi nedir?', 'Oksijeni bağlayarak nitrojenazı korumak ve bakterilere oksijen sağlamak', ['Havadaki azotu nitrojenaza gerek kalmadan doğrudan amonyağa çevirip bitkiye vermek', 'Nodüle kırmızı renk vererek ışık soğurmak', 'Bakterilerin fotosentez yapmasını sağlamak'], 'Leghemoglobin serbest oksijen düzeyini çok düşük tutar; böylece hem nitrojenaz bozulmaz hem de bakterilerin ATP üretimi için oksijen ulaşır.'),
  ('Aynı solunum ölçer deneyi KOH konmadan yapıldığında, karbonhidrat yakan tohumlarda gaz hacmi neden neredeyse hiç değişmez?', 'Tüketilen O₂ hacmine eşit hacimde CO₂ üretilmesi', ['Tohumların KOH olmadığında solunum yapmayı tamamen bırakıp uyku hâline geçmesi', 'Kireç suyunun bütün gazları tutması', 'Tohumların fotosentezle oksijen üretmesi'], 'Karbonhidrat için RQ = 1\'dir; tüketilen O₂ ile üretilen CO₂ eşit hacimdedir, toplam gaz hacmi değişmez.'),
  ('Hücre solunumu ile fotosentezdeki elektron akışlarının yönü karşılaştırıldığında hangisi doğrudur?', 'Solunumda elektronlar besinden O₂\'ye, fotosentezde sudan NADP⁺\'ya akar.', ['İkisinde de elektronlar oksijenden suya doğru akar ve bu akış ATP harcanarak sağlanır.', 'Solunumda elektronlar sudan glikoza, fotosentezde glikozdan suya akar.', 'İkisinde de elektronlar NADP⁺\'dan suya akar.'], 'Solunum ekzergoniktir ve elektronlar yokuş aşağı oksijene iner; fotosentezde ışık enerjisi elektronları sudan yokuş yukarı NADP⁺\'ya taşır.'),
  ('Fotosentezde üretilen ATP\'nin bitki hücresinin diğer işleri yerine büyük ölçüde Kalvin döngüsünde kullanılması nasıl açıklanır?', 'Kloroplastta üretilen ATP\'nin çoğunun stromada şeker yapımında harcanması', ['Kloroplastta üretilen ATP\'nin hücre zarından kolayca ve büyük miktarda dışarı pompalanması', 'Mitokondrilerin bitki hücresinde hiç bulunmaması', 'Fotosentezin ATP yerine glikoz üretmemesi'], 'Fotosentezin ATP\'si stromada Kalvin döngüsüne harcanır; hücrenin geri kalanı için ATP ağırlıkla mitokondride solunumla üretilir.'),
  ('Gündüz fotosentez yapan bir yaprak hücresinde mitokondrilerin ATP üretimini sürdürmesinin nedeni nedir?', 'Kloroplast ATP\'sinin stromada kalıp hücreye yetmemesi', ['Mitokondrilerin ışıktan doğrudan enerji soğurarak gündüz daha fazla ATP üretebilmesi', 'Kloroplastların gündüz hiç ATP üretmemesi', 'Mitokondrilerin yalnız oksijen üretmesi'], 'Sitoplazmadaki protein sentezi, taşıma ve büyüme gibi işler için gereken ATP gündüz de mitokondriden sağlanır.'),
  ('Işıklı bir ortamda tutulan yaprak parçasına radyoaktif ¹⁴CO₂ verildikten bir süre sonra yaprak karanlığa alınıyor. Karanlıkta yaprağın verdiği CO₂\'de radyoaktivite bulunması neyi gösterir?', 'Işıkta bağlanan karbonun solunumla yeniden CO₂\'ye yükseltgendiğini', ['Karanlıkta ¹⁴C\'nin kendiliğinden kararlı ¹²C\'ye dönüştüğünü', 'Yaprağın karanlıkta fotosentez yaptığını', '¹⁴CO₂\'nin hiç bağlanmadan yaprakta beklediğini'], 'Fotosentezle şekere geçen işaretli karbon, solunumda şekerin yıkılmasıyla tekrar CO₂ olarak açığa çıkar.'),
  ('James Sumner\'ın 1926\'da üreaz enzimini saf kristal hâlinde elde etmesi hangi tartışmayı büyük ölçüde sonlandırmıştır?', 'Enzimlerin protein yapıda olup olmadığı tartışmasını', ['Enzimlerin yalnızca hayvanlarda bulunduğu yönündeki tartışmayı', 'Fotosentezde oksijenin kaynağına ilişkin tartışmayı', 'DNA\'nın kalıtım maddesi olduğuna dair tartışmayı'], 'Sumner üreazın kristalinin protein olduğunu gösterdi; Northrop\'un pepsin ve tripsin çalışmalarıyla birlikte enzimlerin protein olduğu kabul gördü (1946 Nobel).'),
  ('Fritz Lipmann\'ın 1941\'de ortaya koyduğu ve hücrede enerji akışının merkezine ATP\'yi koyan kavram hangisidir?', 'Yüksek enerjili fosfat bağı ve ATP\'nin evrensel enerji taşıyıcısı olması', ['Elektron taşıma zincirinin kloroplastta değil yalnız çekirdekte bulunması', 'Enzimlerin yalnız RNA\'dan oluşması', 'Fotosentezde oksijenin CO₂\'den gelmesi'], 'Lipmann, ATP\'yi hücrenin \'enerji para birimi\' olarak tanımladı; koenzim A\'yı da keşfederek 1953\'te Nobel aldı.'),
  ('Bir enzimin etkinleşme enerjisini düşürürken substratı \'geçiş hâli\' denen kararsız yapıya yaklaştırması nasıl gerçekleşir?', 'Aktif bölgenin geçiş hâline substrattan daha sıkı bağlanması', ['Enzimin tepkimeye kendi kimyasal enerjisini ekleyip ürünlerin enerjisini artırması', 'Enzimin ürünleri tepkimeden önce sentezlemesi', 'Enzimin ortam sıcaklığını yükseltmesi'], 'Aktif bölge geçiş hâlini kararlı kılacak biçimde kurulmuştur; geçiş hâlinin enerjisi düşer ve tepkime hızlanır.'),
  ('Bazı ilaçlar, bir enzimin geçiş hâline benzeyen kararlı moleküller olarak tasarlanır. Bu ilaçların çok etkili inhibitör olmasının nedeni nedir?', 'Aktif bölgeye substrattan çok daha sıkı bağlanmaları', ['Enzimin amino asit dizisini kalıcı olarak değiştirip yeni bir enzime dönüştürmeleri', 'Enzimin sentezini çekirdekte durdurmaları', 'Ürünlerle tepkimeye girip onları yok etmeleri'], 'Aktif bölge en güçlü etkileşimi geçiş hâliyle kurar; geçiş hâli benzerleri bu nedenle çok yüksek ilgiyle bağlanır.'),
  ('Aktif bölgedeki bazı amino asitlerin substrata proton verip alarak tepkimeyi hızlandırmasına ne ad verilir?', 'Asit-baz katalizi', ['Kovalent inhibisyon', 'Fotoliz', 'Hidrofobik bağlanma'], 'Histidin gibi yan zincirleri proton alıp verebilen amino asitler geçiş hâlini kararlı kılar.'),
  ('Bir enzimin aktif bölgesindeki serin amino asidinin substratla geçici bir kovalent bağ kurduğu kataliz türüne ne ad verilir?', 'Kovalent kataliz', ['Geri dönüşümsüz inhibisyon', 'Allosterik düzenleme', 'Fotokataliz'], 'Kovalent katalizde enzim-substrat arasında geçici kovalent ara ürün oluşur ve sonra yıkılır; enzim tepkime sonunda eski hâline döner.'),
  ('Kinaz enzimlerinin çoğunun ATP\'yi yalnız Mg²⁺ ile kompleks oluşturmuş hâlde substrat olarak kullanmasının nedeni nedir?', 'Mg²⁺\'nin fosfatların negatif yüklerini kısmen dengelemesi', ['Magnezyumun ATP\'ye ek enerji katıp onu çok daha yüksek enerjili bir moleküle dönüştürmesi', 'Magnezyumun ATP\'yi glikoza dönüştürmesi', 'Mg²⁺\'nin enzimi denatüre etmesi'], 'Mg²⁺ fosfat gruplarına bağlanarak yükleri dengeler ve ATP\'yi aktif bölgede doğru konuma yerleştirir.'),
  ('McArdle hastalığında kas glikojen fosforilazı eksiktir. Bu hastalarda hangi belirti beklenir?', 'Yoğun egzersizde erken yorgunluk ve kas krampları', ['Dinlenme sırasında bile kan şekerinin sürekli olarak çok yüksek düzeyde seyretmesi', 'Kemiklerin aşırı uzaması', 'Gece görme bozukluğu'], 'Kas glikojenini yıkamayan hastalar ani yoğun egzersizde gerekli glikozu sağlayamaz; kaslar çabuk yorulur ve kramp girer.'),
  ('Fenilketonüride diyetteki fenilalaninin kısıtlanmasına karşın tirozinin önemli bir besin hâline gelmesinin nedeni nedir?', 'Normalde fenilalaninden yapılan tirozinin üretilememesi', ['Tirozinin fenilalanini doğrudan parçalayan bir enzim olması', 'Tirozinin vücutta enerji için tek kaynak olması', 'Tirozinin karaciğerde glikojene dönüşmesi'], 'Fenilalanin hidroksilaz eksikliğinde fenilalanin tirozine çevrilemez; tirozin dışarıdan alınması gereken bir amino asit hâline gelir.'),
  ('Glioksilat döngüsünü Krebs döngüsünden ayıran iki özgün enzim hangileridir?', 'İzositrat liyaz ve malat sentaz', ['Rubisko ve PEP karboksilaz', 'Heksokinaz ve fosfofruktokinaz', 'Laktat dehidrogenaz ve alkol dehidrogenaz'], 'İzositrat liyaz izositratı süksinat ve glioksilata ayırır; malat sentaz glioksilata ikinci bir asetil-KoA ekleyerek malat yapar.'),
  ('Glikoz başına elektron taşıma zincirinde 12 su molekülü oluştuğu hâlde oksijenli solunumun net denkleminde 6 su yazılmasının nedeni nedir?', 'Krebs döngüsü ve glikolizin bazı basamaklarında su harcanması', ['ETS\'de oluşan suyun yarısının hemen buharlaşıp hücreden uçması', 'Suyun yarısının glikozun yapısına geri girmesi', 'Denklemde suyun yalnız yarısının gösterilmesinin bir gelenek olması'], 'Fumarattan malat oluşumu, sitrat sentezi ve diğer basamaklarda toplam 6 su kullanılır; net denklem 12 − 6 = 6 suyu gösterir.'),
  ('Bazı bitkilerde bulunan floroasetat, hücrede floroasetil-KoA\'ya ve oradan florositrata dönüşerek akonitazı engeller. Bu zehirlenme hangi yolun durmasına yol açar?', 'Krebs döngüsü', ['Kalvin döngüsü', 'Pentoz fosfat yolu', 'Beta oksidasyonun ilk basamağı ve karnitin taşıması'], 'Florositrat akonitazı engeller; sitrat birikir ve döngü durur. Zehrin vücutta \'ölümcül sentezle\' oluşması dikkat çekicidir.'),
  ('Arsenit, lipoik asit koenzimine bağlanarak pirüvat dehidrogenazı engeller. Bu zehirlenmede kanda hangi maddenin birikmesi beklenir?', 'Pirüvat ve laktat', ['Asetil-KoA ve sitrat', 'Karbondioksit', 'Oksaloasetat ve malat'], 'Pirüvat asetil-KoA\'ya çevrilemez; birikir ve bir kısmı laktata indirgenir.'),
  ('Siyanür zehirlenmesinde hücreler oksijen kullanamadığı için kandaki oksijen düzeyi yüksek kalır. Bu durumda toplardamar kanının renginde ne gözlenebilir?', 'Normalden daha parlak kırmızı olması', ['Normalden çok daha koyu, mora yakın ve siyahımsı bir renk alması', 'Tamamen renksiz olması', 'Yeşile dönmesi'], 'Dokular oksijeni almadığı için toplardamar kanı da oksijence zengin kalır ve atardamar kanı gibi parlak kırmızı görünür.'),
  ('Bazı kişilerde alkol aldıktan sonra yüzde kızarma ve çarpıntı görülür. Bu tepkinin metabolik nedeni nedir?', 'Aldehit dehidrogenazın etkinliği düşük olduğu için asetaldehitin birikmesi', ['Alkol dehidrogenazın tamamen bulunmadığı için etanolün hiç yıkılamayıp kanda kalması', 'Alkolün doğrudan glikoza dönüşmesi', 'Karaciğerin alkolü yağ asidine hızla çevirmesi'], 'ALDH2 geninin düşük etkinlikli varyantını taşıyanlarda asetaldehit yavaş yıkılır ve damar genişlemesine yol açar.'),
  ('Çok miktarda alkol alan kişilerde karaciğerde NADH/NAD⁺ oranının yükselmesi hangi soruna katkıda bulunur?', 'Glukoneogenezin yavaşlayıp kan şekerinin düşmesi', ['Fotosentezin karaciğer hücrelerinde başlayıp kan şekerini aşırı yükseltmesi', 'Kas glikojeninin aşırı artması', 'Böbreklerin daha fazla glikoz üretmesi'], 'Alkol yıkımı çok NADH üretir; bu dengesizlik laktatın ve oksaloasetatın glikoza çevrilmesini engeller, aç karnına alkol hipoglisemiye yol açabilir.'),
  ('Uzun süreli aşırı alkol kullanımında karaciğerde yağ birikmesi (yağlı karaciğer) görülmesinin bir nedeni nedir?', 'Bol NADH\'nin yağ asidi yıkımını baskılayıp yağ sentezini kolaylaştırması', ['Alkolün karaciğerde doğrudan ve hiç değişmeden yağ dokusu hücrelerine dönüşmesi', 'Alkolün yağ asitlerini suya çevirmesi', 'Karaciğerin glikojen yapmayı bırakıp nişasta depolaması'], 'Yüksek NADH beta oksidasyonu yavaşlatır, gliserol-3-fosfat ve yağ asidi sentezini artırır; trigliseritler birikir.'),
  ('Fotosentez yapan hücrelerde fotosistem II\'deki D1 proteininin çok hızlı yıkılıp yeniden sentezlenmesi neyi gösterir?', 'Işıkla sürekli hasar gören bu proteinin yenilenerek onarıldığını', ['Bu proteinin fotosentezde hiçbir görevi olmadığını ve hücrenin onu boşuna ürettiğini', 'Proteinin yalnız gece sentezlendiğini', 'Proteinin glikoz deposu olarak kullanıldığını'], 'D1 proteini yükseltgen hasara en çok maruz kalan bileşendir; hızlı yıkım ve yeniden yapım döngüsü PSII\'nin işlevini korur.'),
  ('İbuprofenin siklooksijenaza (COX) etkisi ile aspirininki karşılaştırıldığında hangisi doğrudur?', 'İbuprofen geri dönüşümlü, aspirin geri dönüşümsüz engeller.', ['İkisi de enzimi kovalent bağla kalıcı olarak etkisizleştirir ve etkileri haftalarca sürer.', 'İbuprofen enzimi etkinleştirir, aspirin engeller.', 'İkisi de COX\'u değil, ATP sentazı engeller.'], 'İbuprofen aktif bölgeye kovalent olmayan bağlarla bağlanır ve vücuttan atılınca etki biter; aspirin ise enzimi asetilleyerek kalıcı olarak bozar.'),
  ('Krebs döngüsünde sitratın izositrata dönüştürülmesinin amacı nedir?', 'Molekülü yükseltgenebilecek bir biçime getirmek', ['Molekülden iki karbonu karbondioksit olarak uzaklaştırıp hemen dört karbonlu bir ürün oluşturmak', 'Molekülü glikoza çevirmek', 'ATP sentezlemek'], 'Akonitaz hidroksil grubunun yerini değiştirir; izositrattaki ikincil alkol grubu dehidrogenaz tarafından yükseltgenebilir.'),
  ('Krebs döngüsünde malatın oksaloasetata yükseltgenmesinin standart serbest enerji değişimi pozitiftir. Döngünün buna rağmen yürüyebilmesi nasıl açıklanır?', 'Oksaloasetatın sitrat sentazca hızla tüketilip derişiminin çok düşük tutulması', ['Malat dehidrogenazın tepkimeye dışarıdan ışık enerjisi ekleyerek onu kendiliğinden yürür hâle getirmesi', 'Malatın doğrudan oksijenle yanması', 'Bu basamağın hücrede hiç gerçekleşmemesi'], 'Ürünün hemen ekzergonik bir sonraki basamakta kullanılması gerçek ΔG\'yi negatif yapar; ardışık tepkimelerin eşleşmesine güzel bir örnektir.'),
  ('Mitokondride bir NADH\'nin elektron çifti bir oksijen atomunu suya indirgerken yaklaşık 2,5 ATP oluşur. Buna göre tüketilen her O₂ molekülü başına kaç ATP oluşur?', '5', ['2,5', '1,25', '10'], 'Bir O₂ molekülü iki oksijen atomudur ve iki NADH\'nin elektronlarını alır: 2 × 2,5 = 5 ATP. Oksijen atomu başına bu değer (P/O oranı) 2,5\'tir.'),
  ('Hücrenin \'enerji yükü\' ATP, ADP ve AMP oranlarına göre hesaplanır. Enerji yükü yüksekken hangi yollar baskın olur?', 'ATP harcayan yapım (anabolik) yolları', ['ATP üreten yıkım yolları ve fermantasyon', 'Yalnız glikoliz', 'Hiçbir metabolik yol çalışmaz'], 'ATP bolken yıkım yolları yavaşlar, biyosentez yolları uyarılır; enerji azalınca bunun tersi olur.'),
  ('AMP ile etkinleşen protein kinaz (AMPK) hücrede enerji azaldığında hangi yanıtı başlatır?', 'Yıkım yollarını açıp yapım yollarını kapatmak', ['Yağ ve protein sentezini hızlandırıp hücrede bol miktarda depo madde biriktirmek', 'Hücreyi fotosentez yapmaya yönlendirmek', 'Mitokondrileri hücreden atmak'], 'AMPK bir \'yakıt göstergesidir\': AMP artınca glikoz alımını ve yağ asidi yıkımını artırır, yağ ve kolesterol sentezini baskılar.'),
  ('Su bitkilerinin bir kısmının sudaki bikarbonatı (HCO₃⁻) da karbon kaynağı olarak kullanabilmesinin önemi nedir?', 'Suda çözünmüş CO₂\'nin az ve yavaş yayılmasını telafi etmesi', ['Sudaki oksijeni bikarbonata dönüştürerek havadan tamamen bağımsız biçimde solunum yapabilmeleri', 'Bikarbonatın ışık enerjisini soğurması', 'Suyun ışığı daha iyi geçirmesini sağlaması'], 'CO₂ suda havaya göre yaklaşık 10 000 kat daha yavaş yayılır; bikarbonat kullanımı sucul fotosentezi kolaylaştırır.'),
  ('Bir bitkinin yaprakları ışıktayken ortamın CO₂ derişimi yükseltildiğinde stomalarının kısmen kapanması bitkiye ne kazandırır?', 'Daha az su kaybederek yeterli CO₂ alabilmeyi', ['Daha çok su kaybederek yaprak sıcaklığını hızla düşürmeyi ve fotosentezi durdurmayı', 'Fotosentezi tamamen bırakmayı', 'Solunumu tamamen durdurmayı'], 'CO₂ boldur ve daha dar stoma açıklığı yeterlidir; böylece terleme azalır ve su kullanım verimi artar.'),
  ('Fotosentezde soğurulan kırmızı fotonun enerjisi mavi fotondan düşük olduğu hâlde ikisi de aynı fotokimyasal işi yapabilir. Bunun nedeni nedir?', 'Mavi fotonun fazla enerjisinin ısıya dönüşüp klorofilin en düşük uyarılmış düzeye inmesi', ['Mavi fotonun kırmızı fotondan çok daha fazla elektron koparıp her soğurulmada iki kat NADPH üretmesi', 'Kırmızı ışığın yaprakta maviye dönüşmesi', 'Mavi ışığın hiç soğurulmaması'], 'Klorofil mavi ışıkla daha yüksek bir düzeye uyarılır, ancak bu fazla enerji hızla ısıya dönüşür; fotokimya en düşük uyarılmış düzeyden başlar.'),
  ('Kırmızı ışığın mavi ışığa göre fotosentezde \'foton başına\' daha verimli kullanılması ne anlama gelir?', 'Soğurulan enerjinin daha az kısmının ısı olarak boşa gitmesi', ['Kırmızı fotonların mavi fotonlardan daha yüksek enerji taşıması ve fazladan ATP üretmesi', 'Kırmızı ışığın karotenoitlerce soğurulması', 'Kırmızı ışığın stomaları kapatması'], 'Her iki foton da aynı işi yapar; kırmızı fotonun enerjisi en düşük uyarılmış düzeye yakın olduğundan boşa giden enerji daha azdır.'),
  ('Chaim Weizmann\'ın Birinci Dünya Savaşı sırasında geliştirdiği ve Clostridium bakterileriyle nişastadan elde edilen önemli endüstriyel ürünler hangileridir?', 'Aseton ve bütanol', ['Penisilin ve streptomisin antibiyotikleri', 'Etanol ve laktik asit', 'Sitrik asit ve sirke'], 'Weizmann\'ın aseton-bütanol-etanol fermantasyonu savaş döneminde patlayıcı yapımı için gereken asetonu sağladı.'),
  ('Kalp kası hücrelerinin kandan aldığı laktatı yakıt olarak kullanabilmesi nasıl gerçekleşir?', 'Laktatın pirüvata yükseltgenip mitokondride yakılması', ['Laktatın doğrudan ve hiç değişmeden ATP sentazın substratı olarak kullanılması', 'Laktatın kalpte nişastaya dönüştürülmesi', 'Laktatın kalpte fermantasyonla etanole çevrilmesi'], 'Laktat dehidrogenaz tepkimesi tersinirdir; oksijence zengin kalp kasında laktat pirüvata çevrilip oksijenli solunumla kullanılır.'),
  ('Bir ATP molekülünün hidrolizi yaklaşık 30,5 kJ/mol enerji verir. Bir sporcu bir saatte yaklaşık 2000 kJ enerji harcıyorsa bu sürede kaç mol ATP yıkılıp yeniden sentezlenmiş olur?', 'Yaklaşık 66', ['Yaklaşık 6', 'Yaklaşık 610', 'Yaklaşık 0,66'], '2000 / 30,5 ≈ 65,6 mol ATP; ATP\'nin mol kütlesi yaklaşık 507 g olduğundan bu, 30 kg\'ı aşan bir ATP döngüsü demektir.'),
  ('Bir enzim deneyinde 25 °C\'de dakikada 12 µmol ürün oluşurken 35 °C\'de 30 µmol ürün oluşuyor. Bu enzim için sıcaklık katsayısı (Q₁₀) kaçtır?', '2,5', ['1,5', '3', '18'], 'Q₁₀ = (35 °C\'deki hız) / (25 °C\'deki hız) = 30 / 12 = 2,5.'),
  ('Bir enzimin etkinliği pH 2, 5 ve 8\'de ölçülüyor ve en yüksek etkinlik pH 8\'de bulunuyor. Bu sonuçtan hangi yargıya kesin olarak varılamaz?', 'Enzimin optimum pH\'ının tam olarak 8 olduğuna', ['Enzimin pH 8\'de pH 2\'dekinden daha etkin olduğuna', 'Enzim etkinliğinin pH\'tan etkilendiğine', 'Enzimin pH 5\'te pH 8\'dekinden daha az etkin olduğuna'], 'Yalnız üç noktada ölçüm yapıldığı için optimum 7 ya da 9 gibi ölçülmeyen bir değer olabilir; daha sık aralıklarla ölçüm gerekir.'),
  ('Bir öğrenci bir enzimin 37 °C\'de en hızlı çalıştığını bulup \'Bu enzimin bütün koşullarda en uygun sıcaklığı 37 °C\'dir.\' diyor. Bu genellemenin zayıf yanı nedir?', 'Optimum sıcaklığın ölçüm süresine ve diğer koşullara bağlı olabilmesi', ['Enzimlerin hiçbir koşulda sıcaklıktan etkilenmediğinin ve hızın sabit kaldığının bilinmesi', 'Enzimlerin yalnız 0 °C\'de çalışması', '37 °C\'nin bütün canlılar için zorunlu sıcaklık olması'], 'Kısa süreli ölçümlerde daha yüksek sıcaklıklar hızlı görünür, uzun sürede ise denatürasyon baskın olur; pH ve iyon ortamı da optimumu kaydırır.'),
  ('Bir enzimin etkinliği tepkime ortamına NaCl eklenince arttı, ancak aynı derişimde Na₂SO₄ eklenince değişmedi. En makul yorum hangisidir?', 'Etkinliği artıran iyonun klorür olduğu', ['Etkinliği artıran iyonun sodyum olduğu ve bunun kesin olarak kanıtlandığı', 'Tuzların enzim etkinliğini hiç etkilemediği', 'Sülfatın enzimin substratı olduğu'], 'İki tuzda da sodyum bulunduğu hâlde yalnız NaCl etkili olduğuna göre fark klorürden kaynaklanır; tükürük amilazı da klorürle etkinleşen bir enzimdir.'),
  ('Bir enzim etkinliği uluslararası birim sisteminde \'katal\' ile ifade edilir. 1 katal neye karşılık gelir?', 'Saniyede 1 mol substratı dönüştüren katalitik etkinliğe', ['Dakikada 1 mikromol substratı dönüştüren ve klinikte en sık kullanılan etkinliğe', '1 gram saf enzim proteinine', 'Enzimin denatüre olduğu sıcaklığa'], 'Katal (kat) SI birimidir: 1 kat = 1 mol/s. Klinikte yaygın kullanılan \'enzim birimi\' (U) ise dakikada 1 µmol\'e karşılık gelir.'),
  ('Patateslerin buzdolabında uzun süre saklanınca tatlılaşmasının nedeni nedir?', 'Soğukta nişasta yıkımının, şekerin solunumla tüketiminden hızlı olması', ['Soğuğun patatesin kabuğunda fotosentezi başlatarak dışarıdan sürekli yeni şeker üretmesi', 'Patatesin soğukta havadaki şekeri emmesi', 'Soğuğun proteinleri şekere çevirmesi'], 'Düşük sıcaklıkta solunum yavaşlarken nişasta yıkımı sürer; indirgen şekerler birikir ve tat tatlılaşır.'),
  ('Bir çiftçi tarlasında aynı ışık koşullarında yetişen mısırın buğdaydan daha az su harcayarak birim alanda daha çok kuru madde ürettiğini gözlüyor. Bunun en uygun açıklaması nedir?', 'Mısırın C4 bitkisi olup stomaları daha az açıkken de CO₂ bağlayabilmesi', ['Buğdayın C4 bitkisi olduğu için sıcakta stomalarını tamamen açık tutup çok su kaybetmesi', 'Mısırın fotosentez yerine kemosentez yapması', 'Buğdayın hiç solunum yapmaması'], 'PEP karboksilazın CO₂\'ye yüksek ilgisi sayesinde C4 bitkileri daha dar stoma açıklığıyla yeterli karbon alır; su kullanım verimleri yüksektir.'),
  ('Bir metabolik yolun tamamının toplam ΔG\'sinin negatif olması gerekirken, yoldaki bazı tekil basamakların ΔG\'si pozitif olabilir. Bu nasıl mümkündür?', 'Pozitif basamaklar, ürünleri hızla tüketen ekzergonik basamaklarla eşleştiği için yürür.', ['Pozitif ΔG\'li basamaklar hücrede enzimsiz ve kendiliğinden, dışarıdan enerji almadan yürür.', 'Hücre bu basamaklarda enerji yaratır.', 'Bu basamaklar yalnız ters yönde çalışır.'], 'Ardışık tepkimelerde gerçek ΔG derişimlere bağlıdır; sonraki basamak ürünü sürekli çektiğinde önceki basamak ileri yönde ilerler.'),
  ('Hücrede ATP gerektiren bir tepkimede ATP\'nin genellikle doğrudan \'enerji vermek\' yerine substrata ya da enzime fosfat aktarması neyi sağlar?', 'Fosforlanmış ara ürünün daha tepkimeye yatkın hâle gelmesini', ['Fosfatın tepkime sonunda glikoza dönüşerek hücreye besin sağlamasını', 'Enzimin kalıcı olarak etkisizleşmesini', 'Tepkimenin ısı soğurarak soğumasını'], 'ATP\'nin enerjisi genellikle fosfat aktarımıyla kullanılır; fosforlanan molekül daha yüksek serbest enerjili ve tepkimeye hazır olur.'),
  ('Hücre içinde ATP/ADP oranının yaklaşık 10 gibi dengeden çok uzak bir değerde tutulmasının önemi nedir?', 'ATP hidrolizinin gerçek serbest enerji değişiminin büyük olmasını sağlaması', ['ATP\'nin hücrede hiçbir koşulda yıkılmamasını ve kalıcı olarak depolanmasını sağlaması', 'ADP\'nin glikoza dönüşmesini sağlaması', 'ATP\'nin hücre dışına salgılanmasını sağlaması'], 'Oran dengeden ne kadar uzaksa hidrolizden elde edilen gerçek enerji o kadar fazladır; hücrede ATP hidrolizinin ΔG\'si standart değerden belirgin biçimde daha negatiftir.'),
  ('Tilakoit zarında fotosistem II ağırlıkla üst üste yığılmış granum bölgelerinde, fotosistem I ve ATP sentaz ise daha çok hangi bölgelerde bulunur?', 'Stromaya bakan, yığılmamış zar bölgelerinde', ['Kloroplastın dış zarında ve zarlar arası boşlukta', 'Tilakoit boşluğunun içinde serbest hâlde', 'Kloroplast DNA\'sının çevresinde'], 'PSI ve ATP sentaz stromaya uzanan büyük bölümleri nedeniyle stroma lamelleri ve granum kenarlarında yoğunlaşır; ürünleri doğrudan stromaya verilir.'),
  ('Kloroplastın iç zarındaki trioz fosfat taşıyıcısı, stromadan sitoplazmaya bir trioz fosfat çıkarırken karşılığında ne alır?', 'Bir inorganik fosfat', ['Bir glikoz molekülü', 'Bir oksijen molekülü', 'Bir NADPH ve bir ATP molekülü'], 'Bu karşılıklı değişim kloroplastın fosfat dengesini korur; sitoplazmada sakkaroz yapılırken açığa çıkan fosfat kloroplasta geri döner.'),
  ('Sitoplazmada sakkaroz sentezi yavaşlayıp inorganik fosfat azaldığında kloroplastta neler olur?', 'Trioz fosfat dışarı çıkamaz ve kloroplastta nişasta birikir.', ['Kloroplast fotosentezi tamamen durdurup bütün şekerini hemen mitokondriye gönderir.', 'Kloroplast doğrudan sakkaroz üretmeye başlar.', 'Kalvin döngüsü daha hızlı çalışır.'], 'Taşıyıcı fosfat karşılığında çalıştığı için fosfat azalınca trioz fosfat stromada kalır ve nişastaya dönüştürülür.'),
  ('Işık tepkimelerinin iki su molekülünden başlayan bir turunda (dört elektron) devirsiz akışla yaklaşık hangi ürünler oluşur?', '1 O₂, 2 NADPH ve yaklaşık 3 ATP', ['2 O₂, 4 NADPH ve 8 ATP', '1 O₂, 1 NADPH ve 1 ATP', '1 CO₂, 2 NADH, 2 FADH₂ ve 2 ATP'], 'Dört elektron 2 NADP⁺\'yı indirger; pompalanan yaklaşık 12 proton ATP sentazda yaklaşık 3 ATP üretir.'),
  ('Clostridium türlerinin yaptığı bütirik asit fermantasyonunda pirüvattan gelen elektronların bir kısmının hidrojen gazı olarak açığa çıkması hücreye ne kazandırır?', 'Fazla elektronların atılarak NAD⁺ dengesinin korunması', ['Hidrojen gazının hücrede ATP\'ye dönüştürülerek fazladan enerji sağlaması', 'Oksijenin hücrede üretilmesi', 'CO₂\'nin bağlanıp şekere çevrilmesi'], 'Fermantasyonda elektronların bir yere bırakılması gerekir; protonların H₂\'ye indirgenmesi indirgen taşıyıcıları yeniden yükseltgemenin bir yoludur.'),
  ('Folik asit eksikliğinin özellikle hızla bölünen hücreleri etkilemesinin metabolik nedeni nedir?', 'DNA yapımı için gereken nükleotitlerin sentezlenememesi', ['Bu hücrelerin glikozu hiç kullanamaması ve yalnız yağ asitleriyle beslenmek zorunda kalması', 'Bu hücrelerin mitokondrilerinin tamamen kaybolması', 'Bu hücrelerde fotosentezin durması'], 'Timin ve pürin sentezi tek karbon aktarımına bağlıdır; DNA eşlenmesi aksayınca kan hücresi yapımı gibi hızlı bölünmeler bozulur.'),
  ('Pirüvat dehidrogenaz kompleksinin çalışması için gerekli beş koenzim hangi seçenekte doğru verilmiştir?', 'TPP, lipoik asit, KoA, FAD ve NAD⁺', ['Biyotin, folat, B12, C vitamini ve ATP', 'NADP⁺, plastokinon, ferredoksin, klorofil ve ATP', 'Hem, ubikinon, sitokrom c, bakır ve demir'], 'Bu kompleks üç enzim ve beş koenzimle çalışır; dördü B vitaminlerinden türer (B1, B5, B2, B3).'),
  ('Bir katalizörün tepkimeyi hızlandırırken ileri ve geri tepkimeler üzerindeki etkisi için hangisi doğrudur?', 'İkisini de aynı oranda hızlandırır.', ['Yalnız ileri tepkimeyi hızlandırır ve geri tepkimeyi tamamen durdurur.', 'Yalnız geri tepkimeyi hızlandırır.', 'İkisini de yavaşlatır.'], 'Etkinleşme enerjisi düşerken ileri ve geri yönün enerji engeli aynı miktarda azalır; denge sabiti değişmez, dengeye daha çabuk ulaşılır.'),
  ('Bir maya kültürüne 1. karbonu ¹⁴C ile işaretlenmiş glikoz veriliyor ve maya oksijensiz ortamda fermantasyon yapıyor. İşaretli karbon hangi ürünlerde bulunur?', 'Yalnız etanolde', ['Yalnız karbondioksitte', 'Hem etanolde hem karbondioksitte eşit olarak', 'Hiçbir üründe'], 'Glikozun 1. karbonu glikolizde pirüvatın metil karbonuna (3. karbon) geçer; alkol fermantasyonunda CO₂ pirüvatın 1. karbonundan çıktığı için işaret etanolde kalır.'),
  ('Yaprakları ışıkta duran bir bitkinin ölçülen net CO₂ alımı sıfır olarak bulunuyor. Bu ölçümden hangi sonuç kesin olarak çıkarılamaz?', 'Bitkinin fotosentez yapmadığı', ['Bitkinin net karbon kazanmadığı', 'Brüt fotosentez hızının solunum hızını aşmadığı', 'Ortamdaki CO₂ miktarının bitki nedeniyle değişmediği'], 'Net değerin sıfır olması fotosentezin solunumla dengelendiğini de gösterebilir; fotosentezin hiç olmadığı sonucuna varılamaz.'),
  ('Karanlıkta bekletilen kloroplastlara çok kısa ışık flaşları verildiğinde oksijen çıkışının her dört flaşta bir en yüksek değere ulaştığı gözlenmiştir. Bu bulgu neyi gösterir?', 'Oksijen çıkaran kompleksin dört elektronu tek tek biriktirdiğini', ['Her ışık flaşının dört ayrı O₂ molekülünü aynı anda açığa çıkardığını', 'Fotosistem I\'in suyu parçaladığını', 'Oksijenin CO₂\'den geldiğini'], 'Kok döngüsü olarak bilinen bu model, kompleksin S₀\'dan S₄\'e dört basamakta yükseltgenip sonra O₂ bıraktığını açıklar.'),
  ('Bir allosterik enzimin \'T (gergin) hâli\' ile \'R (gevşek) hâli\' arasındaki fark için hangisi doğrudur?', 'R hâli substrata daha yüksek ilgi gösterir.', ['T hâli substrata daha yüksek ilgi gösterir ve etkinleştiriciler onu kararlı kılar.', 'İki hâl arasında etkinlik farkı yoktur.', 'T hâli yalnız denatüre olmuş enzimi ifade eder.'], 'Etkinleştiriciler ve substrat R hâlini, baskılayıcılar T hâlini kararlı kılar; bu denge kooperatifliğin temelidir.'),
  ('Bir enzim çözeltisine substrat eklendikten hemen sonra milisaniyeler içinde ürün oluşumunun hızla başladığı, sonra sabit bir hıza oturduğu gözleniyor. Sabit hızlı bu döneme ne ad verilir?', 'Kararlı durum', ['Denatürasyon evresi', 'Geri dönüşümsüz inhibisyon evresi', 'Allosterik kapanma ve enzim yıkımı evresi'], 'Kısa bir başlangıçtan sonra enzim-substrat kompleksinin derişimi sabit kalır; Michaelis-Menten çözümlemesi bu kararlı durum varsayımına dayanır.'),
  ('Fotosentez yapan bir hücrede ışık tepkimeleri ve Kalvin döngüsünün eşgüdümünde NADP⁺ derişiminin rolü hangisidir?', 'NADP⁺ tükenirse devirsiz akış yavaşlar ve devirli akış artar.', ['NADP⁺ arttıkça hücre fotosentezi bırakıp yalnız solunum yapmaya ve oksijen tüketmeye başlar.', 'NADP⁺\'nın ışık tepkimeleriyle hiçbir ilgisi yoktur.', 'NADP⁺ doğrudan oksijene dönüşür.'], 'Kalvin döngüsü NADPH\'yi kullanmadığında NADP⁺ azalır; elektronlar ferredoksinden sitokrom b₆f\'ye geri döner ve yalnız ATP üretilir.'),
  ('Hem fotosentezde hem solunumda kullanılan ATP sentazın dönen yapısının bazı bakterilerdeki ters çalışması (ATP harcayıp proton pompalaması) hangi durumda yararlıdır?', 'Oksijensiz ortamda zar boyunca proton farkını korumak için', ['Işıklı ortamda hücrenin fotosentezle ürettiği fazla oksijeni zarın dışına atmak için', 'Hücre duvarını yıkmak için', 'DNA\'yı eşlemek için'], 'Solunum yapamayan fermantatif bakteriler, glikolizden elde ettikleri ATP\'yi harcayarak taşıma ve hareket için gerekli proton farkını oluşturabilir.'),
  ('Glikozdan gelen karbonun yağ asidi sentezi için mitokondriden sitoplazmaya çıkarılması hangi molekül aracılığıyla olur?', 'Sitrat', ['Asetil-KoA\'nın kendisi', 'Laktat', 'Glikojen'], 'Asetil-KoA iç zardan geçemez; oksaloasetatla sitrat oluşturup dışarı çıkar ve sitoplazmada yeniden asetil-KoA\'ya ayrılır.'),
  ('Açlık sırasında karaciğerin keton cisimciği ürettiği hâlde kendisinin bu cisimcikleri yakıt olarak kullanmaması, karaciğerin hangi rolünü yansıtır?', 'Diğer dokulara yakıt sağlayan bir \'tedarikçi\' olmasını', ['Karaciğerin enerji gereksiniminin olmamasını ve hücrelerinin hiç ATP harcamamasını', 'Karaciğerin keton cisimciklerini oksijenle tepkimeye sokamamasını', 'Karaciğerin yalnız fotosentezle beslenmesini'], 'Karaciğer keton cisimciklerini yıkacak bir enzimden yoksundur; böylece bu yakıt tamamen beyin, kalp ve kaslara kalır.'),
];
